}
#dd input,#dd select{
  padding:8px 12px;
  height:38px;
  border:1.5px solid var(--line);
  border-radius:8px;
  font:inherit;
  font-size:.88rem;
  color:var(--ink);
  background:#fff;
  box-sizing:border-box;
}
#dd #d-prac{
  flex:1 1 auto;
  min-width:0;
  max-width:100%;
  height:38px !important;
  font-weight:600;
  cursor:pointer;
  background-color:#fff;
}
#dd button,#dd a.btn{
  height:38px;
  padding:0 14px;
  border:1.5px solid var(--line);
  border-radius:8px;
  background:#fff;
  color:var(--ink);
  font:inherit;
  font-size:.88rem;
  font-weight:700;
  cursor:pointer;
  text-decoration:none;
  display:inline-flex;
  align-items:center;
  justify-content:center;
  transition:all .15s ease;
  white-space:nowrap;
  box-sizing:border-box;
}
#dd button:hover,#dd a.btn:hover{background:var(--bg);border-color:var(--brand)}
