#dd #refresh:hover{background:var(--brand-dark)}
#dd #today{background:#f4f9f6;color:var(--brand);border-color:var(--line);font-weight:700}
#dd #prev,#dd #next{flex:0 0 auto;padding:0 10px}
#dd #d-date{flex:1 1 auto;min-width:0;text-align:center;font-weight:700}
#dd input:focus,#dd select:focus,#dd button:focus-visible,#dd a:focus-visible{outline:3px solid #8cc9b5;outline-offset:1px}

/* Chips Filter */
#dd .chips{display:flex;flex-wrap:wrap;gap:8px;margin:4px 0 18px}
#dd .chips button{
  padding:7px 14px;
  border-radius:20px;
  border:1.5px solid var(--line);
  background:#fff;
  color:var(--mute);
  font-weight:700;
  font-size:.88rem;
  cursor:pointer;
  transition:all .15s ease;
}
#dd .chips button[aria-pressed=true]{
  background:var(--brand);
  border-color:var(--brand);
  color:#fff;
  box-shadow:0 2px 8px rgba(18,92,58,0.25);
}

/* Appointment Cards */
#dd .a{
  display:grid;
  grid-template-columns:110px 1fr;
  gap:6px 16px;
  padding:16px 18px;
  margin-bottom:12px;
  border:1.5px solid var(--line);
  border-left:6px solid var(--brand);
  border-radius:12px;
  background:#fff;
  box-shadow:var(--shadow-sm);
  transition:transform .15s ease,box-shadow .15s ease;
}
#dd .a:hover{transform:translateY(-1px);box-shadow:var(--shadow)}
#dd .a.now{border-left-color:var(--now);background:#fffbf2}
#dd .a.done{border-left-color:var(--line);opacity:.8}
#dd .t strong{display:block;font-size:1.15rem;font-weight:800;color:var(--brand)}
#dd .t span,#dd .m{color:var(--mute);font-size:.9rem}
#dd .a h3{margin:0 0 2px;font-size:1.15rem;font-weight:800;color:var(--ink)}
#dd .m{margin:4px 0}
#dd .m span{margin-right:14px}
#dd .n{margin:8px 0 0;padding:8px 12px;background:var(--bg);border-radius:8px;font-size:.92rem;color:var(--mute)}

/* Card Actions */
#dd .x{grid-column:1/-1;display:flex;flex-wrap:wrap;gap:8px;margin-top:10px;padding-top:10px;border-top:1px dashed var(--line);align-items:center}
#dd .x select.st{flex:0 1 180px;min-width:0;height:38px}
#dd .x select.pm{flex:0 1 130px;min-width:0;height:38px}
#dd .x a.go{
  background:linear-gradient(135deg,#125c3a,#0d3d27);
  border:none;
  color:#fff;
  font-weight:800;
  box-shadow:0 3px 10px rgba(18,92,58,0.25);
}
#dd .x a.go:hover{filter:brightness(1.1)}
#dd .note{padding:12px 16px;border-radius:10px;background:var(--bg);border-left:4px solid var(--ok);font-size:.92rem}
#dd .note.bad{border-color:var(--err);background:#fdf2f2;color:var(--err)}
#dd [hidden]{display:none!important}

@media(max-width:560px){
  #dd{padding:8px 8px 50px}
  #dd .a{grid-template-columns:1fr}
  #dd .x{flex-direction:column;align-items:stretch}
  #dd .x > a,#dd .x > select.st{flex:0 0 auto;width:100%;height:38px}
  #dd .x .inv-controls{width:100%;display:flex;flex-wrap:wrap;gap:6px}
  #dd .x .inv-controls select.pm{flex:1 1 110px;width:auto;height:38px}
  #dd .x .inv-controls button.inv{flex:1 1 auto}
}

