#dh{
  --ink:#11281e;
  --mute:#546a5f;
  --line:#cfe0d7;
  --pri:#125c3a;
  --pri-dark:#0d3d27;
  --bg:#f4f9f6;
  --ok:#125c3a;
  --err:#c0392b;
  --gold:#f1c40f;
  --gold-bg:#fffbe6;
  --gold-border:#f7dc6f;
  --shadow:0 8px 30px rgba(18,92,58,0.08);
  --shadow-sm:0 2px 10px rgba(18,92,58,0.06);
  max-width:1100px;
  margin:0 auto;
  padding:12px 14px 100px;
  color:var(--ink);
  font:15px/1.45 -apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;
  font-variant-numeric:tabular-nums;
  box-sizing:border-box;
}
#dh *{box-sizing:border-box}

#dh .hd{
  display:flex;
  justify-content:space-between;
  align-items:center;
  gap:12px;
  padding:18px 20px;
  background:linear-gradient(135deg,#0d3d27 0%,#125c3a 100%);
  border-radius:14px;
  color:#fff;
  box-shadow:var(--shadow-sm);
  margin-bottom:16px;
}
#dh h1{font-size:1.4rem;font-weight:900;margin:0;color:#fff}
#dh h2{font-size:1.1rem;font-weight:800;color:var(--pri);margin:24px 0 10px}
#dh .sub{margin:2px 0 0;color:#d8efe4;font-size:.84rem}
#dh .rf{
  border:none;
  background:linear-gradient(135deg,#f1c40f,#d4ac0d);
  color:#2b1d00;
  border-radius:999px;
  padding:8px 16px;
  font:inherit;
  font-weight:800;
  font-size:.88rem;
  cursor:pointer;
  box-shadow:0 2px 8px rgba(241,196,15,0.3);
  transition:transform .15s ease;
}
#dh .rf:hover{transform:translateY(-1px)}

#dh .chips{display:flex;gap:8px;overflow-x:auto;padding:4px 2px 12px;scrollbar-width:none}
#dh .chips::-webkit-scrollbar{display:none}
#dh .chip{
  flex:none;
  padding:10px 18px;
  border:1.5px solid var(--line);
  border-radius:999px;
  background:#fff;
  color:var(--mute);
  font:inherit;
  font-weight:700;
  font-size:.92rem;
  box-shadow:var(--shadow-sm);
  cursor:pointer;
  transition:all .15s ease;
}
#dh .chip[aria-pressed=true]{
  background:var(--pri);
  border-color:var(--pri);
  color:#fff;
  box-shadow:0 3px 10px rgba(18,92,58,0.25);
}

#dh .cust{
  display:flex;
  gap:10px;
  align-items:end;
  flex-wrap:wrap;
  margin:0 0 16px;
  background:#fff;
  padding:14px;
  border-radius:12px;
  border:1.5px solid var(--line);
}
#dh .cust label{display:block;font-size:.78rem;font-weight:700;color:var(--mute);margin-bottom:3px}
#dh input{padding:9px 12px;border:1.5px solid var(--line);border-radius:8px;font:inherit;color:var(--ink);background:#fff}
#dh input:focus{outline:3px solid #8cc9b5;border-color:var(--pri)}

#dh .grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}
#dh a.tile{
  display:flex;
  justify-content:space-between;
  align-items:center;
  gap:8px;
  padding:16px 18px;
  border-radius:14px;
  background:#fff;
  color:var(--ink);
  text-decoration:none;
  box-shadow:var(--shadow-sm);
  border:1.5px solid var(--line);
  min-height:82px;
  transition:transform .15s ease,box-shadow .15s ease,border-color .15s ease;
}
#dh a.tile:hover{transform:translateY(-2px);box-shadow:var(--shadow);border-color:var(--pri)}
#dh a.tile b{display:block;font-size:1.3rem;font-weight:900;line-height:1.2;color:var(--pri)}
#dh a.tile span.l{display:block;font-size:.95rem;font-weight:700}
#dh a.tile small{display:block;color:var(--mute);font-size:.78rem;margin-top:2px}
#dh a.tile .ch{flex:none;color:var(--pri);font-size:1.6rem;line-height:1}
#dh a.tile.good{background:#f3faf6;border-color:#a5d6be}
#dh a.tile.bad{background:#fdf4f3;border-color:#f3b7ad}
#dh a.tile.neg b{color:var(--err)}

#dh .sbox{position:relative;margin-bottom:8px}
#dh .sbox input{
  width:100%;
  padding:14px 50px 14px 16px;
  font-size:1rem;
  border-radius:12px;
  border:1.5px solid var(--line);
  background:#fff;
  box-shadow:var(--shadow-sm);
}
#dh .sbox svg{position:absolute;right:16px;top:50%;margin-top:-13px;stroke:var(--pri)}
#dh .res{
  display:flex;
  justify-content:space-between;
  align-items:center;
  gap:10px;
  padding:12px 16px;
  margin-top:8px;
  border:1.5px solid var(--line);
  border-radius:10px;
  background:#fff;
  box-shadow:var(--shadow-sm);
}
#dh .badge{display:inline-block;padding:3px 10px;border-radius:6px;font-weight:800;font-size:.8rem;color:#fff;background:var(--ok)}
#dh .badge.out{background:var(--err)}

#dh .qa{display:grid;grid-template-columns:repeat(auto-fit,minmax(100px,1fr));gap:12px}
#dh .qa a{
  display:flex;
  flex-direction:column;
  align-items:center;
  gap:8px;
  padding:16px 8px;
  border-radius:14px;
  background:#fff;
  color:var(--ink);
  text-decoration:none;
  font-size:.88rem;
  font-weight:700;
  text-align:center;
  box-shadow:var(--shadow-sm);
  border:1.5px solid var(--line);
  transition:all .15s ease;
}
#dh .qa a:hover{transform:translateY(-2px);border-color:var(--pri);color:var(--pri)}
#dh .qa svg{width:32px;height:32px;color:var(--pri)}

#dh .note{padding:12px 14px;margin:0 0 14px;border-radius:8px;background:#fdf2f2;border-left:4px solid var(--err);color:var(--err)}

/* Bottom Nav */
#dh nav.bn{
  position:fixed;
  left:0;
  right:0;
  bottom:0;
  z-index:20;
  display:grid;
  grid-template-columns:repeat(5,1fr);
  background:#fff;
  border-top:1.5px solid var(--line);
  padding:8px 0 calc(8px + env(safe-area-inset-bottom,0px));
  box-shadow:0 -4px 16px rgba(0,0,0,0.06);
}
#dh nav.bn a,#dh nav.bn button{
  display:flex;
  flex-direction:column;
  align-items:center;
  gap:2px;
  border:0;
  background:none;
  color:var(--mute);
  font:inherit;
  font-size:.82rem;
  font-weight:700;
  text-decoration:none;
  cursor:pointer;
  padding:2px 0;
}
#dh nav.bn svg{width:24px;height:24px}
#dh nav.bn .on{color:var(--pri);font-weight:800}

#dh .sheet{
  position:fixed;
  left:0;
  right:0;
