#dh .sheet a{display:block;padding:14px 6px;border-top:1px solid var(--line);color:var(--ink);text-decoration:none;font-weight:700}
#dh .sheet a:first-child{border-top:0}
#dh [hidden]{display:none!important}

@media(min-width:820px){
