#apt{
  --ink:#11281e;
  --mute:#546a5f;
  --line:#cfe0d7;
  --bg:#f4f9f6;
  --brand:#125c3a;
  --brand-dark:#0d3d27;
  --ok:#125c3a;
  --err:#c0392b;
  --gold:#f1c40f;
  --gold-text:#966f00;
  --gold-bg:#fffbe6;
  --gold-border:#f7dc6f;
  --shadow:0 8px 24px rgba(18,92,58,0.08);
  --shadow-sm:0 2px 8px rgba(18,92,58,0.05);
  max-width:560px;
  margin:0 auto;
  padding:14px 16px 48px;
  color:var(--ink);
  font:14px/1.45 -apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;
  box-sizing:border-box;
}
#apt *{box-sizing:border-box}

/* Header */
#apt .top-header{
  text-align:center;
  padding:16px 16px 14px;
  margin-bottom:12px;
  background:linear-gradient(135deg,#0d3d27 0%,#125c3a 100%);
  border-radius:14px;
  color:#fff;
  box-shadow:var(--shadow);
}
#apt .top-badge{
  display:inline-block;
  background:linear-gradient(135deg,#f1c40f,#d4ac0d);
  color:#2b1d00;
  font-size:.68rem;
  font-weight:800;
  letter-spacing:.08em;
  text-transform:uppercase;
  border-radius:20px;
  padding:2px 10px;
  margin-bottom:6px;
}
#apt #btn-dash{
  transition:all .15s ease;
}
#apt #btn-dash:hover{
  background:rgba(255,255,255,0.3)!important;
  border-color:#fff!important;
}
#apt h1{font-size:1.35rem;font-weight:900;margin:0 0 4px;letter-spacing:-.01em;color:#fff}
#apt .lead{color:rgba(255,255,255,0.88);margin:0;font-size:.84rem;line-height:1.4}
#apt .form-lead{color:var(--mute);margin:0 0 10px;font-size:.84rem}

/* Segmented Toggle */
#apt .seg{
  display:grid;
  grid-template-columns:1fr 1fr;
  background:#eef6f2;
  border:1.5px solid var(--line);
  border-radius:10px;
  padding:3px;
  gap:3px;
  margin-bottom:12px;
}
#apt .seg button{
  padding:8px 8px;
  border:0;
  background:none;
  color:var(--mute);
  font:inherit;
  font-weight:700;
  font-size:.88rem;
  cursor:pointer;
  border-radius:8px;
  transition:all .15s ease;
}
#apt .seg button[aria-pressed=true]{
  background:var(--brand);
  color:#fff;
  box-shadow:0 2px 8px rgba(18,92,58,0.22);
}

/* Card & Fieldset */
#apt form{
  background:#fff;
  border:1.5px solid var(--line);
  border-radius:14px;
  padding:18px 18px;
  box-shadow:var(--shadow-sm);
}
#apt fieldset{border:0;padding:0;margin:0 0 16px}
#apt legend{
  font-weight:800;
  font-size:1.02rem;
  color:var(--brand);
  padding:0;
  margin-bottom:8px;
  display:flex;
  align-items:center;
  gap:6px;
}
#apt label{display:block;font-size:.8rem;font-weight:700;color:var(--ink);margin:7px 0 3px}
#apt input,#apt select,#apt textarea{
  width:100%;
  padding:8px 11px;
  border:1.5px solid var(--line);
  border-radius:8px;
  font:inherit;
  font-size:.9rem;
  color:var(--ink);
  background:#fff;
  min-height:38px;
  transition:border-color .15s ease,outline .15s ease;
}
#apt input:focus,#apt select:focus,#apt textarea:focus,#apt button:focus-visible{
  outline:3px solid #8cc9b5;
  outline-offset:1px;
  border-color:var(--brand);
}
#apt .row{display:grid;grid-template-columns:1fr 1fr;gap:8px}
#apt .row-2{display:grid;grid-template-columns:1fr 1fr;gap:8px}

/* Buttons */
#apt .go{
  width:100%;
  margin-top:14px;
  padding:11px 16px;
  border:0;
  border-radius:8px;
  background:linear-gradient(135deg,#125c3a,#0d3d27);
  color:#fff;
  font:inherit;
  font-weight:800;
  font-size:.95rem;
  letter-spacing:.01em;
  cursor:pointer;
  box-shadow:0 3px 12px rgba(18,92,58,0.25);
  transition:transform .15s ease,box-shadow .15s ease;
}
#apt .go:hover:not(:disabled){transform:translateY(-1px);box-shadow:0 5px 16px rgba(18,92,58,0.35)}
#apt .go:disabled{opacity:.55;cursor:wait}
#apt .ghost{
  margin-top:8px;
  padding:8px 14px;
  border:1.5px solid var(--brand);
  border-radius:8px;
  background:#fff;
  color:var(--brand);
  font:inherit;
  font-weight:700;
  font-size:.88rem;
  cursor:pointer;
  transition:background .15s ease;
}
#apt .ghost:hover{background:var(--bg)}

/* Notes & Banners */
#apt .note{margin-top:10px;padding:10px 14px;border-radius:8px;background:var(--bg);border-left:4px solid var(--ok);font-size:.88rem}
#apt .note.bad{border-color:var(--err);background:#fdf2f2;color:var(--err)}
#apt .done{
  margin-bottom:14px;
  border-left:4px solid var(--ok);
  background:#ebf7f1;
  padding:12px 14px;
  border-radius:10px;
  box-shadow:var(--shadow-sm);
}

/* Patient Search Results */
#apt .res{display:grid;gap:8px;margin-top:10px}
#apt .res button{
  display:flex;
  flex-wrap:wrap;
  gap:4px 12px;
  align-items:baseline;
  text-align:left;
  width:100%;
  padding:9px 12px;
  border:1.5px solid var(--line);
  border-radius:8px;
  background:#fff;
  color:var(--ink);
  font:inherit;
  cursor:pointer;
  transition:border-color .15s ease,background .15s ease;
}
#apt .res button:hover{background:var(--bg);border-color:var(--brand)}
#apt .res button strong{flex:1 1 100%;font-size:.95rem;color:var(--brand)}
#apt .res button span{color:var(--mute);font-size:.82rem}
#apt .res button[aria-pressed=true]{border-color:var(--ok);background:#eef7f2;border-width:2px}

/* Upcoming Appointments */
#apt .up{display:flex;justify-content:space-between;gap:8px;align-items:center;padding:8px 0;border-top:1px solid var(--line)}
#apt .up:first-of-type{border-top:0}
#apt [hidden]{display:none!important}

@media(max-width:540px){
  #apt{
    padding:10px 14px 44px;
    max-width:100%;
  }
  #apt form{
    padding:14px 12px;
    border-radius:12px;
  }
  #apt .top-header{
    padding:14px 12px 12px;
    border-radius:12px;
    margin-bottom:10px;
  }
  #apt .top-header h1{
    font-size:1.22rem;
  }
  #apt .top-header .lead{
    font-size:0.78rem;
  }
  #apt .row{grid-template-columns:1fr;gap:6px}
  #apt .row-2{grid-template-columns:1fr 1fr;gap:6px}
  #apt input,#apt select,#apt textarea{
    padding:7px 9px;
    font-size:.86rem;
    min-height:36px;
  }
  #apt label{
    margin:6px 0 2px;
    font-size:.76rem;
  }
}

