.jeevan-banner-container {
        width: 100%;
        background-color: #125c3a;
        padding: 45px 0;
        box-sizing: border-box;
        overflow: visible;
        font-family: 'Cinzel', 'Montserrat', 'Helvetica Neue', sans-serif;
    }

    .jeevan-banner-content {
        display: flex;
        align-items: center;
        width: 100%;
        max-width: 100%;
        margin: 0 auto;
        position: relative;
    }

    /* Left logo container: 20% width with maximum curved radius and generous padding */
    .jeevan-logo-box {
        width: 20%;
        flex: 0 0 20%;
        background-color: #f1c40f; /* Exact solid yellow color */
        border-top-right-radius: 400px;
        border-bottom-right-radius: 400px;
        padding: 30px 65px 30px 30px;
        display: flex;
        align-items: center;
        justify-content: center;
        box-sizing: border-box;
        box-shadow: 4px 0px 18px rgba(0, 0, 0, 0.45);
    }

    .jeevan-logo-img {
        width: 100%;
        height: auto;
        object-fit: contain;
        display: block;
    }

    /* Right typography layout occupying remaining 80% width */
    .jeevan-title-box {
        width: 80%;
        flex: 0 0 80%;
        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: center;
        text-align: center;
        padding: 0 40px;
        box-sizing: border-box;
    }

    /* Maximized text styling with exact solid yellow and embossed 3D shadow effect */
    .jeevan-main-title,
    .jeevan-sub-title-1,
    .jeevan-sub-title-2 {
        margin: 0;
        font-weight: 900;
        letter-spacing: 2.5px;
        line-height: 1.1;
        width: 100%;
        color: #f1c40f; /* Exact solid yellow color */
        text-shadow: 
            -1px -1px 0px #ffeaa7,
             1px  1px 0px #b7950b,
             2px  2px 5px rgba(0, 0, 0, 0.85);
    }

    /* Substantially increased font sizes to completely fill the space */
    .jeevan-main-title {
        font-size: clamp(2rem, 5.5vw, 6rem);
        margin-bottom: 2px;
    }

    .jeevan-sub-title-1 {
        font-size: clamp(1.4rem, 3.8vw, 4rem);
        margin: 2px 0;
    }

    .jeevan-sub-title-2 {
        font-size: clamp(1.8rem, 5vw, 5.5rem);
        margin-top: 2px;
    }

    /* Responsive adjustments for mobile and tablet screens */
    @media (max-width: 768px) {
        .jeevan-banner-container {
            padding: 16px 0;
        }
        .jeevan-logo-box {
            border-top-right-radius: 120px;
            border-bottom-right-radius: 120px;
            padding: 10px 18px 10px 10px;
            box-shadow: 2px 0px 12px rgba(0, 0, 0, 0.35);
        }
        .jeevan-title-box {
            padding: 0 12px;
        }
        .jeevan-main-title {
            font-size: clamp(1.4rem, 4.5vw, 2.4rem);
            letter-spacing: 1.5px;
        }
        .jeevan-sub-title-1 {
            font-size: clamp(1rem, 3.2vw, 1.6rem);
            margin: 1px 0;
            letter-spacing: 1.5px;
        }
        .jeevan-sub-title-2 {
            font-size: clamp(1.3rem, 4.2vw, 2.2rem);
            letter-spacing: 1.5px;
            margin-top: 1px;
        }
    }
    @media (max-width: 480px) {
        .jeevan-banner-container {
            padding: 12px 0;
        }
        .jeevan-banner-content {
            gap: 2px;
        }
        .jeevan-logo-box {
            width: 22%;
            flex: 0 0 22%;
            border-top-right-radius: 70px;
            border-bottom-right-radius: 70px;
            padding: 6px 12px 6px 6px;
        }
        .jeevan-title-box {
            width: 78%;
            flex: 0 0 78%;
            padding: 0 6px;
        }
        .jeevan-main-title {
