#pi{
  --ink:#11281e;
  --mute:#546a5f;
  --line:#cfe0d7;
  --bg:#f4f9f6;
  --brand:#125c3a;
  --brand-dark:#0d3d27;
  --ok:#125c3a;
  --err:#c0392b;
  --gold:#f1c40f;
  --shadow-sm:0 2px 10px rgba(18,92,58,0.06);
  max-width:980px;
  margin:0 auto;
  padding:14px 12px 64px;
  color:var(--ink);
  font:15px/1.55 -apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;
  box-sizing:border-box;
}
#pi *{box-sizing:border-box}

#pi .top-header{
  padding:16px 20px;
  background:linear-gradient(135deg,#0d3d27 0%,#125c3a 100%);
  border-radius:14px;
  color:#fff;
  box-shadow:var(--shadow-sm);
  margin-bottom:16px;
  display:flex;
  justify-content:space-between;
  align-items:center;
  flex-wrap:wrap;
  gap:10px;
}
#pi h1{font-size:1.45rem;font-weight:900;margin:0;color:#fff}
#pi h2{font-size:1.1rem;font-weight:800;color:var(--brand);margin:0 0 10px}
#pi h3{font-size:0.98rem;font-weight:800;margin-bottom:8px;color:var(--ink)}
#pi .card{
  padding:18px;
  margin-bottom:16px;
  border:1.5px solid var(--line);
  border-radius:12px;
  background:#fff;
  box-shadow:var(--shadow-sm);
}
#pi label{display:block;font-size:.84rem;font-weight:700;color:var(--mute);margin:12px 0 4px}
#pi input,#pi select,#pi textarea{
  width:100%;
  padding:10px 12px;
  border:1.5px solid var(--line);
  border-radius:8px;
  font:inherit;
  color:var(--ink);
  background:#fff;
}
#pi input:focus,#pi select:focus,#pi textarea:focus,#pi button:focus-visible{
  outline:3px solid #8cc9b5;
  border-color:var(--brand);
}
#pi textarea{font-family:ui-monospace,Menlo,Consolas,monospace;font-size:.85rem}
#pi .g2{display:grid;grid-template-columns:1fr 1fr;gap:12px}
#pi .g3{display:grid;grid-template-columns:1fr 1fr 1fr;gap:12px}
#pi .g4{display:grid;grid-template-columns:1fr 1fr 1fr 1fr;gap:12px}
#pi .hint{color:var(--mute);font-size:.86rem;margin:8px 0 0;line-height:1.5}
#pi .btn{
  padding:10px 20px;
  border:0;
  border-radius:8px;
  background:var(--ink);
  color:#fff;
  font:inherit;
  font-weight:700;
  cursor:pointer;
  transition:all .15s ease;
  display:inline-flex;
  align-items:center;
  justify-content:center;
  text-decoration:none;
}
#pi .btn:hover{filter:brightness(1.1)}
#pi .btn.go{background:linear-gradient(135deg,#125c3a,#0d3d27);box-shadow:0 3px 10px rgba(18,92,58,0.25)}
#pi .btn.alt{background:#5d7184}
#pi .btn:disabled{opacity:.55;cursor:wait}
#pi .back-link{
  color:var(--brand);
  font-size:.9rem;
  text-decoration:none;
  font-weight:700;
  display:inline-flex;
  align-items:center;
  gap:4px;
  margin-bottom:12px;
}
#pi .back-link:hover{text-decoration:underline}
#pi .note{padding:12px 14px;margin-bottom:14px;border-radius:8px;background:var(--bg);border-left:4px solid var(--ok);font-size:.92rem}
#pi .note.bad{border-color:var(--err);background:#fdf2f2;color:var(--err)}
#pi .scroll{overflow:auto;max-height:380px;border:1.5px solid var(--line);border-radius:8px}
#pi table{width:100%;border-collapse:collapse;font-size:.88rem}
#pi th,#pi td{padding:8px 10px;border-bottom:1px solid var(--line);text-align:left;white-space:nowrap}
#pi th{position:sticky;top:0;background:var(--bg);font-weight:700;color:var(--mute);z-index:2}
#pi td.n,#pi th.n{text-align:right}
#pi tr.bad td{background:#fdf2f2}
#pi .okt{color:var(--ok);font-weight:700}
#pi .bdt{color:var(--err);font-weight:700}
#pi .badge{display:inline-block;padding:2px 8px;background:#ebf7f1;color:var(--ok);border-radius:12px;font-size:.78rem;font-weight:700}
#pi .mute{color:var(--mute)}
#pi [hidden]{display:none!important}

#pi .bill-summary-bar{
  display:flex;
  justify-content:space-between;
  align-items:center;
  background:var(--bg);
  border:1.5px solid var(--line);
  border-radius:10px;
  padding:14px 18px;
  margin-top:14px;
  flex-wrap:wrap;
  gap:12px;
}
#pi .sum-item{display:flex;flex-direction:column}
#pi .sum-lbl{font-size:.78rem;color:var(--mute);font-weight:700;text-transform:uppercase}
#pi .sum-val{font-size:1.15rem;color:var(--ink);font-weight:800}
#pi .sum-val.tot{color:var(--brand);font-size:1.3rem;font-weight:900}

@media(max-width:720px){
  #pi .g2,#pi .g3,#pi .g4{grid-template-columns:1fr}
  #pi .bill-summary-bar{flex-direction:column;align-items:stretch;text-align:left}
}

