    #ci .ln-item-col{grid-column:1 / -1}
    #ci .ln-desc-col{grid-column:1 / -1}
    #ci .ln-amt-box{grid-column:1 / -1;text-align:right;border-top:1px dashed var(--line);padding-top:6px}
  }
  @media(max-width:560px){
    #ci .g2{grid-template-columns:1fr}
    #ci .bar{flex-direction:column;align-items:stretch}
    #ci .bar .actions{display:flex;flex-direction:column;gap:8px}
  }

#cl *{box-sizing:border-box}
  #cl{
    --ink:#11281e;
    --mute:#546a5f;
    --line:#cfe0d7;
    --bg:#f4f9f6;
    --brand:#125c3a;
    --brand-dark:#0d3d27;
    --gold:#f1c40f;
    --shadow:0 8px 28px rgba(18,92,58,0.09);
    --shadow-sm:0 2px 10px rgba(18,92,58,0.06);
    max-width:980px;
    margin:0 auto;
    padding:16px 14px 80px;
    color:var(--ink);
    font:15px/1.55 -apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;
  }
  #cl .hero{
    display:flex;
    justify-content:space-between;
    align-items:center;
    flex-wrap:wrap;
    gap:14px;
    padding:20px 22px;
    margin-bottom:20px;
    background:linear-gradient(135deg,#0d3d27 0%,#125c3a 100%);
    border-radius:16px;
    color:#fff;
    box-shadow:var(--shadow);
  }
  #cl .hero-brand{display:flex;align-items:center;gap:14px}
  #cl .hero-logo{
    width:48px;
    height:48px;
    border-radius:12px;
    background:#fff;
    padding:3px;
    object-fit:contain;
    flex-shrink:0;
    box-shadow:0 2px 8px rgba(0,0,0,.18);
  }
  #cl .hero h1{margin:0;font-size:1.45rem;font-weight:900;color:#fff;letter-spacing:-.01em}
  #cl .hero p{margin:2px 0 0;font-size:.88rem;color:rgba(255,255,255,.86)}
  #cl .hero-actions{display:flex;align-items:center;gap:8px;flex-wrap:wrap}
  #cl .role-pill{
    background:linear-gradient(135deg,#f1c40f,#d4ac0d);
    color:#2b1d00;
    font-size:.74rem;
    font-weight:800;
    padding:4px 11px;
    border-radius:20px;
    text-transform:uppercase;
    letter-spacing:.04em;
  }
  #cl .home-btn{
    display:inline-flex;
    align-items:center;
    gap:5px;
    padding:7px 13px;
    border-radius:9px;
    font-size:.84rem;
    font-weight:700;
    text-decoration:none;
    color:#fff;
    background:rgba(255,255,255,.16);
    border:1.5px solid rgba(255,255,255,.38);
    transition:background .15s ease;
  }
  #cl .home-btn:hover{background:rgba(255,255,255,.28)}
  #cl .grid{
    display:grid;
    grid-template-columns:repeat(auto-fit,minmax(250px,1fr));
    gap:16px;
  }
  #cl .tile{
    display:flex;
    flex-direction:column;
    justify-content:space-between;
    text-decoration:none;
    color:inherit;
    background:#fff;
    border:1.5px solid var(--line);
    border-radius:15px;
    padding:20px;
    box-shadow:var(--shadow-sm);
    transition:transform .16s ease,box-shadow .16s ease,border-color .16s ease;
  }
  #cl .tile:hover{
    transform:translateY(-3px);
    box-shadow:var(--shadow);
    border-color:var(--brand);
  }
  #cl .tile-top{display:flex;align-items:center;gap:12px;margin-bottom:12px}
  #cl .tile-icon{
    width:48px;
    height:48px;
    border-radius:12px;
    display:flex;
    align-items:center;
    justify-content:center;
    font-size:1.55rem;
    background:var(--bg);
    border:1px solid var(--line);
  }
  #cl .tile-title{font-size:1.15rem;font-weight:900;color:var(--ink);margin:0 0 5px}
  #cl .tile-desc{font-size:.87rem;color:var(--mute);margin:0;line-height:1.45}
  #cl .tile-foot{
    margin-top:16px;
    padding-top:11px;
    border-top:1px solid var(--line);
    display:flex;
    justify-content:space-between;
    align-items:center;
    font-size:.84rem;
    font-weight:800;
    color:var(--brand);
  }
  #cl .tile.featured{
    background:linear-gradient(135deg,#ffffff 0%,#f0f8f3 100%);
    border-color:#8cc9b5;
  }
  #cl .state-box{
    text-align:center;
    padding:36px 20px;
    background:#fff;
    border:1.5px solid var(--line);
    border-radius:14px;
    color:var(--mute);
    font-weight:700;
  }
  #cl .err-box{
    padding:14px 16px;
    background:#fdf2f2;
    color:#c0392b;
    border-left:4px solid #c0392b;
    border-radius:8px;
    font-weight:600;
  }
  #cl [hidden]{display:none!important}
  @media(max-width:560px){
    #cl .hero{padding:16px}
    #cl .grid{grid-template-columns:1fr}
  }
